import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.mzJ8I8R4.js";const c=JSON.parse('{"title":"部署服务器","description":"","frontmatter":{},"headers":[],"relativePath":"guide/server.md","filePath":"guide/server.md"}'),o={name:"guide/server.md"};function n(l,s,p,d,h,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="部署服务器" tabindex="-1">部署服务器 <a class="header-anchor" href="#部署服务器" aria-label="Permalink to &quot;部署服务器&quot;">​</a></h1><p>要在多台设备之间同步，或者在浏览器里使用网页版，需要一台自己的服务器。服务端和网页版打包在同一个 Docker 镜像里，部署一次，网页、Android、macOS 和 Windows 都能连上。</p><p>只在一台设备上用的，不需要服务器，见<a href="./local">在本机使用</a>。</p><h2 id="需要准备" tabindex="-1">需要准备 <a class="header-anchor" href="#需要准备" aria-label="Permalink to &quot;需要准备&quot;">​</a></h2><ul><li><strong>一台 Linux 服务器</strong>：云服务商的云服务器（VPS）即可，amd64 或 arm64 都行。NextTodo 占用很少，配置要求不高。</li><li><strong>一个域名</strong>：在域名服务商那里添加一条 A 记录，把一个域名（比如 <code>todo.example.com</code>）指向服务器的公网 IP。在中国大陆的服务器上用域名提供网站，需要先完成备案。</li><li><strong>放行端口</strong>：在云服务商的安全组或防火墙里放行 80 和 443 端口，申请 HTTPS 证书和访问网页都要用到。</li><li><strong>Docker</strong>：按 <a href="https://docs.docker.com/engine/install/" target="_blank" rel="noreferrer">Docker 官方文档</a>在服务器上安装 Docker Engine，它自带 Docker Compose。</li></ul><p>下面的命令都在服务器的终端里运行（用 SSH 登录服务器）。</p><h2 id="_1-启动-nexttodo" tabindex="-1">1. 启动 NextTodo <a class="header-anchor" href="#_1-启动-nexttodo" aria-label="Permalink to &quot;1. 启动 NextTodo&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSLO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/JunieXD/NextTodo/main/deploy/compose.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 65534:65534</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>这几行依次：建一个目录，下载配置文件，建好存放数据的 <code>data</code> 目录，启动 NextTodo。数据库和每日快照都在 <code>data</code> 里。</p><p>NextTodo 现在只在服务器内部的 8080 端口上运行，外面还访问不到，下一步给它配上 HTTPS。</p><h2 id="_2-配置-https" tabindex="-1">2. 配置 HTTPS <a class="header-anchor" href="#_2-配置-https" aria-label="Permalink to &quot;2. 配置 HTTPS&quot;">​</a></h2><p>用 Caddy 最省事，它会自动申请和续期 HTTPS 证书。</p><ol><li><p>按 <a href="https://caddyserver.com/docs/install" target="_blank" rel="noreferrer">Caddy 官方文档</a>在服务器上安装 Caddy。</p></li><li><p>把 <code>/etc/caddy/Caddyfile</code> 的内容换成下面三行，域名换成自己的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>todo.example.com {</span></span>
<span class="line"><span>	reverse_proxy 127.0.0.1:8080</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>运行 <code>sudo systemctl reload caddy</code> 让配置生效。</p></li></ol><p>稍等片刻，用浏览器打开 <code>https://todo.example.com</code>，能看到 NextTodo 的登录页就成功了。已经在用 Nginx 的，配置见<a href="https://github.com/JunieXD/NextTodo/blob/main/docs/deploy.md#%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86" target="_blank" rel="noreferrer">部署文档</a>。</p><h2 id="_3-创建账号并登录" tabindex="-1">3. 创建账号并登录 <a class="header-anchor" href="#_3-创建账号并登录" aria-label="Permalink to &quot;3. 创建账号并登录&quot;">​</a></h2><p>回到 <code>nexttodo</code> 目录，创建管理员账号。下面的 <code>admin</code> 是用户名，可以换成自己想用的（字母、数字和下划线），然后按提示输入两次密码：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nexttodo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /nexttodo-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span></span></code></pre></div><p>然后在 App 里点“连接服务器”，服务器地址填域名（如 <code>todo.example.com</code>），再填用户名和密码登录。浏览器里打开域名就是网页版。</p><h2 id="_4-邀请其他人" tabindex="-1">4. 邀请其他人 <a class="header-anchor" href="#_4-邀请其他人" aria-label="Permalink to &quot;4. 邀请其他人&quot;">​</a></h2><p>每人一个账号，数据彼此独立。管理员在“设置 → 邀请注册”里点“生成邀请码”，邀请链接会自动复制，发给对方即可。对方打开链接，或者在登录页选“邀请码注册”并填入邀请码，就能注册。每个邀请码只能注册一个账号。</p><h2 id="ai" tabindex="-1">5. 让服务器替你整理 <a class="header-anchor" href="#ai" aria-label="Permalink to &quot;5. 让服务器替你整理 {#ai}&quot;">​</a></h2><p><a href="./ai">AI 整理</a>的配置默认只能保存在各自的设备上，整理时设备要联网。想让服务器自己整理、提交后设备可以离线，要给服务器设一个加密密钥：</p><ol><li><p>在 <code>nexttodo</code> 目录里运行下面的命令，生成密钥并写进 <code>.env</code> 文件：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;NEXTTODO_SECRET_KEY=$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div></li><li><p>运行 <code>docker compose up -d</code> 让它生效。</p></li><li><p>在 App 的 AI 整理设置里，保存位置选“同步到服务器”。</p></li></ol><p>服务器用这个密钥加密保存大家的 API 密钥。<code>.env</code> 文件要保管好；换掉或丢了它，已保存的 API 密钥就解不开，要重新填写。</p><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><p>出了新版本时，管理员打开 NextTodo 会看到提示条“服务器可升级到 0.1.N”，设置的“关于”里也写着。想第一时间知道，可以在 <a href="https://github.com/JunieXD/NextTodo" target="_blank" rel="noreferrer">GitHub 仓库</a>右上角点 <strong>Watch</strong> → <strong>Custom</strong>，勾选 <strong>Releases</strong> 后点 <strong>Apply</strong>，发布新版本时 GitHub 会发邮件通知。</p><p>在服务器上的 <code>nexttodo</code> 目录里运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>数据会自动升级，不用另外操作。如果在 <code>.env</code> 里写了 <code>NEXTTODO_IMAGE</code> 固定版本，先把其中的版本号改成新的。</p><p>App 不用手动升级：服务器升级后，各设备的 App 会自动获取新版本。</p><h2 id="备份" tabindex="-1">备份 <a class="header-anchor" href="#备份" aria-label="Permalink to &quot;备份&quot;">​</a></h2><p>服务器每天在 <code>data/snapshots/</code> 里保存一份数据库快照，保留最近 7 份。把这些快照定期复制到别处，就是备份。从快照恢复的步骤见<a href="https://github.com/JunieXD/NextTodo/blob/main/docs/deploy.md#%E5%A4%87%E4%BB%BD%E5%92%8C%E6%81%A2%E5%A4%8D" target="_blank" rel="noreferrer">部署文档</a>。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li>查看 NextTodo 的日志：在 <code>nexttodo</code> 目录里运行 <code>docker compose logs --tail 100</code>。</li><li>网页打不开：检查域名是否已经指向服务器，80 和 443 端口是否放行，Caddy 是否在运行（<code>systemctl status caddy</code>）。</li></ul>`,34)])])}const g=a(o,[["render",n]]);export{c as __pageData,g as default};
